def is_hollow(g,r0,c0,h,w):
    # boundary filled, interior empty
    for i in range(h):
        for j in range(w):
            ii,jj=i,j
            if (ii in(0,h-1) or jj in(0,w-1)):
                if g[r0+ii][c0+jj]==0: return False
            else:
                if g[r0+ii][c0+jj]!=0: return False
    return True

